schema.sdl:
type Query {
  species: [Species!]!
  move(id: Int!): SpeciesMove
}

type Species {
  id: Int!
  name: String!
  moves: [SpeciesMove!]!
}

type SpeciesMove {
  name: String!
  power: Int!
}

inputs.text:
query Board {
  ...QueryFrag
  species {
    id
    ...SpeciesA
    ...SpeciesB
  }
  move(id: 1) {
    ...MoveA
  }
}

fragment MoveA on SpeciesMove {
  name
  power
}

fragment QueryFrag on Query {
  species {
    id
  }
}

fragment SpeciesA on Species {
  id
  name
}

fragment SpeciesB on Species {
  id
  moves {
    name
  }
}

