schema.sdl:
type Query {
  species(id: Int!): Species
}

type Mutation {
  rename(id: Int!, name: String!): Species
}

type Subscription {
  speciesChanged(id: Int!): Species
}

type Species {
  id: Int!
  name: String!
  flavorText: String
  evolutionChain: [Species!]!
  creature: Creature
}

union Creature = Species | Plant

type Plant {
  id: Int!
  height: Int!
}

inputs.text:
query Deferred($id: Int! = 1, $with: Boolean!) @cache(policy: NetworkOnly, partial: true) {
  species(id: $id) {
    id
    name @required
    flavorText @include(if: $with)
    ...SpeciesPreview @defer(label: "preview")
    ...SpeciesName @include(if: $with)
    ...SpeciesId @skip(if: $with)
    ... @defer(label: "Preview") {
      flavorText
    }
    evolutionChain @stream(initialCount: 1, label: "chain") {
      id
    }
    creature {
      ... on Species {
        name
        flavorText @required
        ...SpeciesPreview @defer(label: "creature preview", if: $with)
      }
      ... on Plant {
        height
      }
    }
  }
}

mutation Rename($id: Int!, $name: String!) {
  rename(id: $id, name: $name) @optimisticKey {
    id
    name
  }
}

fragment SpeciesId on Species {
  id
}

fragment SpeciesName on Species {
  name
}

fragment SpeciesPreview on Species {
  flavorText
}

subscription Watch($id: Int!) {
  speciesChanged(id: $id) {
    id
    name
  }
}

