schema.sdl:
type Query {
  favorites(first: Int): [Species!]!
  species(first: Int, after: String): SpeciesConnection!
}

type Mutation {
  addFavorite(id: Int!): AddPayload
}

type AddPayload {
  species: Species!
}

type Species {
  id: Int!
  name: String!
}

type SpeciesConnection {
  edges: [SpeciesEdge!]!
  pageInfo: PageInfo!
}

type SpeciesEdge {
  node: Species!
  cursor: String!
}

type PageInfo {
  hasNextPage: Boolean!
  endCursor: String
}

inputs.text:
mutation AddFavorite($id: Int!) {
  addFavorite(id: $id) {
    species {
      id
      ...Found_toggle
    }
  }
}

query Favorites {
  favorites(first: 10) @list(name: "Found", connection: false) {
    id
    name
  }
}

query Paginated {
  species(first: 2) @paginate(mode: Infinite, name: "Paged_Species") {
    edges {
      node {
        id
        name
      }
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

